import type { HellaChildren } from "@hellajs/dom";

import { css, style } from "@hellajs/css";

const base = style({
  alignItems: "center",
  border: "1px solid var(--input)",
  borderRadius: "calc(var(--radius) * 0.8)",
  boxShadow: "0 1px 2px 0 rgb(0 0 0 / 0.05)",
  display: "flex",
  height: "2.25rem",
  minWidth: "0",
  outlineStyle: "none",
  position: "relative",
  transition: "color 150ms cubic-bezier(0.4, 0, 0.2, 1), box-shadow 150ms cubic-bezier(0.4, 0, 0.2, 1)",
  width: "100%",
  "&:is(.dark *)": {
    background: "color-mix(in oklab, var(--input) 30%, transparent)",
  },
  "&:has(> textarea)": {
    height: "auto",
  },
  "&:has(> [data-align='inline-start']) > input": {
    paddingLeft: "0.5rem",
  },
  "&:has(> [data-align='inline-end']) > input": {
    paddingRight: "0.5rem",
  },
  "&:has(> [data-align='block-start'])": {
    flexDirection: "column",
    height: "auto",
  },
  "&:has(> [data-align='block-start']) > input": {
    paddingBottom: "0.75rem",
  },
  "&:has(> [data-align='block-end'])": {
    flexDirection: "column",
    height: "auto",
  },
  "&:has(> [data-align='block-end']) > input": {
    paddingTop: "0.75rem",
  },
  "&:has([data-slot='input-group-control']:focus-visible)": {
    borderColor: "var(--ring)",
    boxShadow: "0 0 0 3px color-mix(in oklab, var(--ring) 50%, transparent)",
  },
  "&:has([data-slot][aria-invalid='true'])": {
    borderColor: "var(--destructive)",
  },
  "&:has([data-slot][aria-invalid='true']):has([data-slot='input-group-control']:focus-visible)": {
    boxShadow: "0 0 0 3px color-mix(in oklab, var(--destructive) 20%, transparent)",
  },
  "&:is(.dark *):has([data-slot][aria-invalid='true']):has([data-slot='input-group-control']:focus-visible)": {
    boxShadow: "0 0 0 3px color-mix(in oklab, var(--destructive) 40%, transparent)",
  },
}, { label: "hella-input-group", layer: "hella" });

const addon = style({
  alignItems: "center",
  color: "var(--muted-foreground)",
  cursor: "text",
  display: "flex",
  fontSize: "0.875rem",
  fontWeight: "500",
  gap: "0.5rem",
  height: "auto",
  justifyContent: "center",
  paddingBlock: "0.375rem",
  userSelect: "none",
  "& > kbd": {
    borderRadius: "calc(var(--radius) - 5px)",
  },
  "& > svg:not([class*='size-'])": {
    height: "1rem",
    width: "1rem",
  },
}, { label: "hella-input-group-addon", layer: "hella" });

const addonAlign = {
  "inline-start": style({
    order: "-9999",
    paddingLeft: "0.75rem",
    "&:has(> button)": {
      marginLeft: "-0.45rem",
    },
    "&:has(> kbd)": {
      marginLeft: "-0.35rem",
    },
  }, { label: "hella-input-group-addon-inline-start", layer: "hella" }),
  "inline-end": style({
    order: "9999",
    paddingRight: "0.75rem",
    "&:has(> button)": {
      marginRight: "-0.45rem",
    },
    "&:has(> kbd)": {
      marginRight: "-0.35rem",
    },
  }, { label: "hella-input-group-addon-inline-end", layer: "hella" }),
  "block-start": style({
    justifyContent: "flex-start",
