    borderRadius: "calc(var(--radius) - 5px)",
    display: "flex",
    gap: "0.25rem",
    height: "1.5rem",
    paddingInline: "0.5rem",
    boxShadow: "none",
    "&:has(> svg)": {
      paddingInline: "0.5rem",
    },
    "& > svg:not([class*='size-'])": {
      height: "0.875rem",
      width: "0.875rem",
    },
  }, { label: "hella-input-group-size-xs", layer: "hella" }),
  sm: style({
    alignItems: "center",
    borderRadius: "calc(var(--radius) * 0.8)",
    display: "flex",
    gap: "0.375rem",
    height: "2rem",
    paddingInline: "0.625rem",
    boxShadow: "none",
    "&:has(> svg)": {
      paddingInline: "0.625rem",
    },
