    borderRadius: "calc(var(--radius) - 5px)",
    display: "flex",
    height: "1.5rem",
    padding: "0",
    width: "1.5rem",
    boxShadow: "none",
    "&:has(> svg)": {
      padding: "0",
    },
  }, { label: "hella-input-group-size-icon-xs", layer: "hella" }),
  "icon-sm": style({
    alignItems: "center",
    display: "flex",
    height: "2rem",
    padding: "0",
    width: "2rem",
    boxShadow: "none",
    "&:has(> svg)": {
      padding: "0",
    },
  }, { label: "hella-input-group-size-icon-sm", layer: "hella" }),
};

const text = style({
  alignItems: "center",
  color: "var(--muted-foreground)",
  display: "flex",
  fontSize: "0.875rem",
  gap: "0.5rem",
  "& svg": {
    pointerEvents: "none",
  },
  "& svg:not([class*='size-'])": {
    height: "1rem",
    width: "1rem",
  },
}, { label: "hella-input-group-text", layer: "hella" });

const inputBase = style({
