  border: "1px solid var(--input)",
  borderRadius: "calc(var(--radius) * 0.8)",
  boxShadow: "0 1px 2px 0 rgb(0 0 0 / 0.05)",
  fontSize: "1rem",
  height: "2.25rem",
  lineHeight: "1.5rem",
  minWidth: "0",
  outlineStyle: "none",
  paddingBlock: "0.25rem",
  paddingInline: "0.75rem",
  transition: "color 150ms cubic-bezier(0.4, 0, 0.2, 1), box-shadow 150ms cubic-bezier(0.4, 0, 0.2, 1)",
  width: "100%",
  "&::file-selector-button": {
    background: "transparent",
    border: "none",
    color: "var(--foreground)",
    display: "inline-flex",
    fontSize: "0.875rem",
    fontWeight: "500",
    height: "1.75rem",
  },
  "&::placeholder": {
    color: "var(--muted-foreground)",
  },
  "&::selection": {
    backgroundColor: "var(--primary)",
    color: "var(--primary-foreground)",
  },
  "&:disabled": {
    cursor: "not-allowed",
    opacity: "0.5",
    pointerEvents: "none",
  },
  "@media (min-width: 48rem)": {
    "&": {
      fontSize: "0.875rem",
      lineHeight: "1.25rem",
    },
  },
  "&:is(.dark *)": {
    background: "color-mix(in oklab, var(--input) 30%, transparent)",
  },
}, { label: "hella-input-group-input", layer: "hella" });

const inputFocus = style({
  "&:focus-visible": {
    borderColor: "var(--ring)",
    boxShadow: "0 0 0 3px color-mix(in oklab, var(--ring) 50%, transparent)",
  },
}, { label: "hella-input-group-input-focus", layer: "hella" });

const inputInvalid = style({
  "&[aria-invalid='true']": {
    borderColor: "var(--destructive)",
  },
  "&[aria-invalid='true']:focus-visible": {
    boxShadow: "0 0 0 3px color-mix(in oklab, var(--destructive) 20%, transparent)",
  },
  "&:is(.dark *)[aria-invalid='true']:focus-visible": {
    boxShadow: "0 0 0 3px color-mix(in oklab, var(--destructive) 40%, transparent)",
  },
}, { label: "hella-input-group-input-invalid", layer: "hella" });

const inputControl = style({
  background: "transparent",
  borderRadius: "0",
  borderWidth: "0",
  flex: "1 1 0%",
  boxShadow: "none",
  "&:focus-visible": {
    boxShadow: "none",
  },
  "&:is(.dark *)": {
    background: "transparent",
  },
}, { label: "hella-input-group-input-control", layer: "hella" });

const textareaBase = style({
  border: "1px solid var(--input)",
  borderRadius: "calc(var(--radius) * 0.8)",
  boxShadow: "0 1px 2px 0 rgb(0 0 0 / 0.05)",
  display: "flex",
  fieldSizing: "content",
  minHeight: "4rem",
  outlineStyle: "none",
  paddingBlock: "0.5rem",
  paddingInline: "0.75rem",
  transition: "color 150ms cubic-bezier(0.4, 0, 0.2, 1), box-shadow 150ms cubic-bezier(0.4, 0, 0.2, 1)",
  width: "100%",
  "&::placeholder": {
    color: "var(--muted-foreground)",
  },
  "&:disabled": {
    cursor: "not-allowed",
    opacity: "0.5",
  },
  "@media (min-width: 48rem)": {
    "&": {
      fontSize: "0.875rem",
      lineHeight: "1.25rem",
    },
  },
  "&:is(.dark *)": {
    background: "color-mix(in oklab, var(--input) 30%, transparent)",
  },
}, { label: "hella-input-group-textarea", layer: "hella" });

const textareaFocus = style({
  "&:focus-visible": {
    borderColor: "var(--ring)",
    boxShadow: "0 0 0 3px color-mix(in oklab, var(--ring) 50%, transparent)",
  },
}, { label: "hella-input-group-textarea-focus", layer: "hella" });

const textareaInvalid = style({
  "&[aria-invalid='true']": {
    borderColor: "var(--destructive)",
  },
  "&[aria-invalid='true']:focus-visible": {
    boxShadow: "0 0 0 3px color-mix(in oklab, var(--destructive) 20%, transparent)",
  },
  "&:is(.dark *)[aria-invalid='true']:focus-visible": {
    boxShadow: "0 0 0 3px color-mix(in oklab, var(--destructive) 40%, transparent)",
  },
}, { label: "hella-input-group-textarea-invalid", layer: "hella" });

const textareaControl = style({
  background: "transparent",
  borderRadius: "0",
  borderWidth: "0",
  flex: "1 1 0%",
  paddingBlock: "0.75rem",
  resize: "none",
  boxShadow: "none",
  "&:focus-visible": {
    boxShadow: "none",
  },
  "&:is(.dark *)": {
    background: "transparent",
  },
}, { label: "hella-input-group-textarea-control", layer: "hella" });

css({
  "@layer hella": {
    "[data-slot='input-group'][data-disabled='true'] [data-slot='input-group-addon']": {
      opacity: "0.5",
    },
    "[data-slot='input-group']:has(input) [data-slot='input-group-addon'][data-align='block-start']": {
      paddingTop: "0.625rem",
    },
    "[data-slot='input-group']:has(input) [data-slot='input-group-addon'][data-align='block-end']": {
      paddingBottom: "0.625rem",
    },
    ".border-b [data-slot='input-group-addon'][data-align='block-start'], .border-b ~ [data-slot='input-group-addon'][data-align='block-start']": {
      paddingBottom: "0.75rem",
    },
    ".border-t [data-slot='input-group-addon'][data-align='block-end'], .border-t ~ [data-slot='input-group-addon'][data-align='block-end']": {
      paddingTop: "0.75rem",
    },
  },
});

interface InputGroupProps {
  children?: HellaChildren;
  /** Renders data-disabled="true" on the group; addons read it for their opacity state. */
  disabled?: boolean;
  class?: string;
}

export default function InputGroup(props: InputGroupProps): JSX.Element {
  return (
    <div
      data-slot="input-group"
      role="group"
      data-disabled={props.disabled ? "true" : undefined}
      class={
        [base, props.class]
      }
    >
      {props.children}
    </div>
  );
}

interface InputGroupAddonProps {
  children?: HellaChildren;
  align?: "inline-start" | "inline-end" | "block-start" | "block-end";
  class?: string;
}

export function InputGroupAddon(props: InputGroupAddonProps): JSX.Element {
  return (
    <div
      role="group"
      data-slot="input-group-addon"
      data-align={props.align ?? "inline-start"}
      class={
        [
          addon,
          addonAlign[props.align ?? "inline-start"],
          props.class,
        ]
      }
      on:click={(e: Event) => {
        const target = e.target as HTMLElement;
        if (target.closest("button")) return;
        target.closest('[data-slot="input-group"]')?.querySelector("input")?.focus();
      }}
    >
      {props.children}
    </div>
  );
}

interface InputGroupButtonProps {
  children?: HellaChildren;
  type?: string;
  variant?: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link";
  size?: "xs" | "sm" | "icon-xs" | "icon-sm";
  class?: string;
  onclick?: () => void;
}

export function InputGroupButton(props: InputGroupButtonProps): JSX.Element {
  return (
    <button
      type={props.type ?? "button"}
      data-slot="button"
      data-variant={props.variant ?? "ghost"}
      data-size={props.size ?? "xs"}
      class={
        [
          buttonBase,
          buttonVariants[props.variant ?? "ghost"],
          buttonSizes[props.size ?? "xs"],
          sizes[props.size ?? "xs"],
          props.class,
        ]
      }
      on:click={() => props.onclick?.()}
    >
      {props.children}
    </button>
  );
}

interface InputGroupTextProps {
  children?: HellaChildren;
  class?: string;
}

export function InputGroupText(props: InputGroupTextProps): JSX.Element {
  return (
    <span
      data-slot="input-group-text"
      class={
        [text, props.class]
      }
    >
      {props.children}
    </span>
  );
}

interface InputGroupInputProps {
  value?: string | (() => string);
  type?: string;
  placeholder?: string;
  id?: string;
  ariaLabel?: string;
  ariaInvalid?: boolean;
  class?: string;
  oninput?: (v: string) => void;
}

export function InputGroupInput(props: InputGroupInputProps): JSX.Element {
  return (
    <input
      data-slot="input-group-control"
      type={props.type}
      placeholder={props.placeholder}
      id={props.id}
      ariaLabel={props.ariaLabel}
      aria-invalid={props.ariaInvalid ? "true" : undefined}
      value={props.value}
      class={
        [
          inputBase,
          inputFocus,
          inputInvalid,
          inputControl,
          props.class,
        ]
      }
      on:input={(e: Event) => props.oninput?.((e.target as HTMLInputElement).value)}
    />
  );
}

interface InputGroupTextareaProps {
  value?: string | (() => string);
  placeholder?: string;
  id?: string;
  ariaLabel?: string;
  rows?: number;
  ariaInvalid?: boolean;
  class?: string;
  oninput?: (v: string) => void;
}

export function InputGroupTextarea(props: InputGroupTextareaProps): JSX.Element {
  return (
    <textarea
      data-slot="input-group-control"
      placeholder={props.placeholder}
      id={props.id}
      ariaLabel={props.ariaLabel}
      rows={props.rows}
      aria-invalid={props.ariaInvalid ? "true" : undefined}
      value={props.value}
      class={
        [
          textareaBase,
          textareaFocus,
          textareaInvalid,
          textareaControl,
          props.class,
        ]
      }
      on:input={(e: Event) => props.oninput?.((e.target as HTMLTextAreaElement).value)}
    />
  );
}

